    throw new Error("RUNPOD_HUMO_IDENTITY_PROBE_AUDIO_SHA256_MISMATCH");
}

patch.replace:
const parseJsonStringArray = (raw, fallback = []) => {
    const text = String(raw || "").trim();
    if (!text) return fallback.filter(Boolean).map(value => String(value).trim()).filter(Boolean);
    let parsed;
    try { parsed = JSON.parse(text); }
    catch { throw new Error("RUNPOD_HUMO_IDENTITY_PROBE_REFERENCE_SET_INVALID"); }
    if (!Array.isArray(parsed)) throw new Error("RUNPOD_HUMO_IDENTITY_PROBE_REFERENCE_SET_INVALID");
    return parsed.map(value => String(value || "").trim()).filter(Boolean);
};
const referenceOutputs = parseJsonStringArray(
    env.JARVIS_HUMO_IDENTITY_PROBE_REFERENCE_OUTPUTS_JSON,
    [env.JARVIS_HUMO_IDENTITY_PROBE_REFERENCE_OUTPUT]
);
const expectedReferenceSha256s = parseJsonStringArray(
    env.JARVIS_HUMO_IDENTITY_PROBE_REFERENCE_SHA256S_JSON,
    [env.JARVIS_HUMO_IDENTITY_PROBE_REFERENCE_SHA256]
).map(value => value.toLowerCase());
if (referenceOutputs.length < 1 || referenceOutputs.length > 3 || expectedReferenceSha256s.length !== referenceOutputs.length) {
    throw new Error("RUNPOD_HUMO_IDENTITY_PROBE_REFERENCE_SET_INVALID");
}
const references = referenceOutputs.map(output => resolveSourceArtifact(
    output,
    [".jpg", ".jpeg", ".png", ".webp"],
    "RUNPOD_HUMO_IDENTITY_PROBE_REFERENCE_INVALID"
));
const audio = resolveSourceArtifact(
    env.JARVIS_HUMO_IDENTITY_PROBE_AUDIO_OUTPUT,
    [".wav"],
    "RUNPOD_HUMO_IDENTITY_PROBE_AUDIO_INVALID"
);
const sha256File = file => createHash("sha256").update(fs.readFileSync(file)).digest("hex");
references.forEach((reference, index) => {
    const expected = expectedReferenceSha256s[index];
    if (!/^[a-f0-9]{64}$/.test(expected) || sha256File(reference.file) !== expected) {
        throw new Error("RUNPOD_HUMO_IDENTITY_PROBE_REFERENCE_SHA256_MISMATCH");
    }
});
const expectedAudioSha256 = String(env.JARVIS_HUMO_IDENTITY_PROBE_AUDIO_SHA256 || "").trim().toLowerCase();
if (!/^[a-f0-9]{64}$/.test(expectedAudioSha256) || sha256File(audio.file) !== expectedAudioSha256) {
    throw new Error("RUNPOD_HUMO_IDENTITY_PROBE_AUDIO_SHA256_MISMATCH");
}
